mapper.select:
SELECT mb.market_id AS id, m.create_time, m.market_name, m.market_logo, m.market_desc, m.goods_num, m.sub_bind_num, m.sell_num, m.sell_amount FROM market_bind mb left join market m on mb.market_id = m.id
and mb.user_id = #{query.clientId}
and mb.bind_type = #{query.bindType}
and m.market_level = #{query.marketLevel}
and m.market_name like CONCAT('%',#{query.marketName},'%')
${query.sortSQL}

SELECT mgr.id, mgr.goods_id, mgr.sell_num, mgr.create_time, mgr.market_id, mgr.discount_rate, sp.sale_num, sp.`name`, sp.img, sp.sale_price_began, sp.sale_price_end, sp.state, sp.market_price, sp.selection_num, m.market_name, sp.max_profit, sp.supplier_price_began, sp.supplier_price_end FROM market_bind mb LEFT JOIN market m ON mb.market_id = m.id LEFT JOIN market_goods_relation mgr ON mgr.market_id = m.id LEFT JOIN spu sp ON mgr.goods_id = sp.id
and mb.user_id = #{query.userId}
and mb.bind_type = #{query.bindType}
and mgr.market_id = #{query.marketId}
and mgr.relation_type = #{query.relationType}
and mgr.goods_id = #{query.goodsId}
${query.buildInSQL('goodsIdList', 'mgr.goods_id')}
and sp.`name` like CONCAT('%',#{query.goodsName},'%')
and sp.category_id = #{query.categoryId}
and sp.`state` = #{query.spuState}
${query.sortSQL}
